{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_c348ebf0f07e1c58abfd0fd0", "claim_ids": ["claim_0a50ecadd0df177db60358aa", "claim_aea2919075df783a2d6c890b"], "query_ids": ["q_405"], "claims": [{"claim_id": "claim_0a50ecadd0df177db60358aa", "quote": "Average import price for spodumene concentrate under HS Code 26179000 was $0.84.", "url": "https://www.zauba.com/import-spodumene+concentrate/hs-code-26179000-hs-code.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "spodumene concentrate", "duty_rate": "$0.84"}}, {"claim_id": "claim_aea2919075df783a2d6c890b", "quote": "Spodumene Concentrate worth $485,583 under HS Code 26179000 have been imported", "url": "https://www.zauba.com/import-spodumene+concentrate/hs-code-26179000-hs-code.html", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "Spodumene Concentrate", "duty_rate": "$485,583"}}]}, {"pair_id": "conflict_44bf9c3ed3cd3a1631c76da1", "claim_ids": ["claim_1256d84b5649950a2309fdcc", "claim_f610fd08614a1949e67265bc"], "query_ids": ["q_406"], "claims": [{"claim_id": "claim_1256d84b5649950a2309fdcc", "quote": "USTR previously announced new tariffs on natural flake graphite on May 14, 2024, increasing to 25% in 2026.", "url": "https://www.novonixgroup.com/news/united-states-government-to-reinstate-section-301-import-tariffs-on-artificial-graphite-from-china", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "NOVONIX", "tariff_program": "Section 301 tariffs", "affected_product": "natural flake graphite", "announcement_date": "May 14, 2024"}}, {"claim_id": "claim_f610fd08614a1949e67265bc", "quote": "During the review of the \"Section 301 Tariffs,\" the U.S. announced a 25% tariff on natural graphite, but postponed its implementation until 2026.", "url": "https://www.linkedin.com/pulse/impact-us-tariffs-chinas-natural-graphite-exports-supply-chain-arohc", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "natural graphite", "duty_rate": "25%", "effective_date": "2026"}}]}, {"pair_id": "conflict_ff5462db077eb8bad6f3d7a9", "claim_ids": ["claim_556cfa3a97903420232cca19", "claim_ca929b9b15435e761d28ccf0"], "query_ids": ["q_406"], "claims": [{"claim_id": "claim_556cfa3a97903420232cca19", "quote": "The US government renewed 25% tariﬀs on them, eﬀective immediately, in June 2024.", "url": "https://graphitealliance.org/wp-content/uploads/2024/10/NAGA-Potential-Tariffs-on-Graphite.pdf", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariﬀs", "effective_date": "June 2024"}}, {"claim_id": "claim_ca929b9b15435e761d28ccf0", "quote": "The US government installed 25% tariﬀs on the same products in September 2024: 2504.10.10 – Natural graphite, crystalline ﬂake (not including ﬂake dust)", "url": "https://graphitealliance.org/wp-content/uploads/2024/10/NAGA-Potential-Tariffs-on-Graphite.pdf", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "25% tariﬀs", "effective_date": "September 2024"}}]}, {"pair_id": "conflict_dfe030e6eeba3b0dff5fbd40", "claim_ids": ["claim_2f4b593fab27c7803d2b9607", "claim_35682faac50590587f78f031"], "query_ids": ["q_407"], "claims": [{"claim_id": "claim_2f4b593fab27c7803d2b9607", "quote": "Natural graphite, other than in powder or in flakes 25% 2026", "url": "https://ustr.gov/sites/default/files/Section%20301%20Modifications%20Determination%20FRN%20(Sept%2012%202024)%20(FINAL).pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Natural graphite, other than in powder or in flakes", "duty_rate": "25%", "effective_date": "2026"}}, {"claim_id": "claim_35682faac50590587f78f031", "quote": "Natural Graphite: The President directed the U.S. Trade Representative to increase tariffs on natural graphite to 25 percent in 2026.", "url": "https://ustr.gov/sites/default/files/Section%20301%20Modifications%20Determination%20FRN%20(Sept%2012%202024)%20(FINAL).pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "natural graphite", "duty_rate": "25 percent", "effective_date": "2026"}}]}, {"pair_id": "conflict_9c793ee068b78d2b170a59e1", "claim_ids": ["claim_5af0edf5521fb010ee73ee92", "claim_7c9dd91eaffaa3c13a1ee041"], "query_ids": ["q_407"], "claims": [{"claim_id": "claim_5af0edf5521fb010ee73ee92", "quote": "• Natural graphite – Increase rate to 25% in 2026", "url": "https://ustr.gov/sites/default/files/Section%20301%20Modifications%20Determination%20FRN%20(Sept%2012%202024)%20(FINAL).pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Natural graphite", "duty_rate": "25%", "effective_date": "2026"}}, {"claim_id": "claim_7c9dd91eaffaa3c13a1ee041", "quote": "Natural graphite in powder or flakes (other than crystalline flake) 25% 2026", "url": "https://ustr.gov/sites/default/files/Section%20301%20Modifications%20Determination%20FRN%20(Sept%2012%202024)%20(FINAL).pdf", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Natural graphite in powder or flakes (other than crystalline flake)", "duty_rate": "25%", "effective_date": "2026"}}]}, {"pair_id": "conflict_f7ff27348e2aff29a96ee0a3", "claim_ids": ["claim_8dad2700eda9a631038f87fa", "claim_b9791db44304c420c89c91db"], "query_ids": ["q_409"], "claims": [{"claim_id": "claim_8dad2700eda9a631038f87fa", "quote": "The US has no nickel sulphate production and imports most of its material from Belgium and Australia, which exported 1,872t and 1,060t to the US last year, respectively. Tariffs on Belgium will fall under the EU, which will be applied at 20pc, while Australia is subject to a tariff of 10pc.", "url": "https://www.argusmedia.com/en/news-and-insights/latest-market-news/2674679-us-battery-costs-face-sharp-rise-on-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "nickel sulphate", "exporting_country": "Australia", "duty_rate": "10pc"}}, {"claim_id": "claim_b9791db44304c420c89c91db", "quote": "Key materials that are not exempt include nickel sulphate, manganese sulphate, phosphoric acid, iron phosphate and synthetic graphite, all of which will be included in the tariff regimes implemented on individual countries.", "url": "https://www.argusmedia.com/en/news-and-insights/latest-market-news/2674679-us-battery-costs-face-sharp-rise-on-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "nickel sulphate", "country_of_origin": "Belgium", "exporting_country": "Belgium", "duty_rate": "20pc"}}]}, {"pair_id": "conflict_8bf37b2ca692b3bdcae797a8", "claim_ids": ["claim_8dad2700eda9a631038f87fa", "claim_bb08dfbc0589c67bb8d8caf2"], "query_ids": ["q_409"], "claims": [{"claim_id": "claim_8dad2700eda9a631038f87fa", "quote": "The US has no nickel sulphate production and imports most of its material from Belgium and Australia, which exported 1,872t and 1,060t to the US last year, respectively. Tariffs on Belgium will fall under the EU, which will be applied at 20pc, while Australia is subject to a tariff of 10pc.", "url": "https://www.argusmedia.com/en/news-and-insights/latest-market-news/2674679-us-battery-costs-face-sharp-rise-on-tariffs", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "nickel sulphate", "exporting_country": "Australia", "duty_rate": "10pc"}}, {"claim_id": "claim_bb08dfbc0589c67bb8d8caf2", "quote": "However, several critical materials will be impacted, including nickel sulphate, manganese sulphate, phosphoric acid, iron phosphate, and synthetic graphite. These materials will fall under country-specific tariff regimes.", "url": "https://christopherchico.substack.com/p/trumps-tariff-hike-what-it-means", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "nickel sulphate", "duty_rate": "64.9%"}}]}, {"pair_id": "conflict_97f3f02fc2100cae0a46bb6b", "claim_ids": ["claim_47d89b05b66af179a3a59120", "claim_e4ed4462b93e198fe5dc6135"], "query_ids": ["q_41"], "claims": [{"claim_id": "claim_47d89b05b66af179a3a59120", "quote": "Import of agricultural goods, food products, clothes, construction materials, wood and wood products, plastics, wire and cable, iron, steel, soap, organic surface-active agents, and washing preparations which are produced in Georgia in whole or in part, are major areas of goods taxed at higher rates.", "url": "https://www.trade.gov/country-commercial-guides/georgia-import-tariffs", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "higher rates", "affected_product": "plastics", "country_of_origin": "Georgia"}}, {"claim_id": "claim_e4ed4462b93e198fe5dc6135", "quote": "Rates of duty on imported goods fall into three bands: zero percent, five percent, and 12 percent.", "url": "https://www.trade.gov/country-commercial-guides/georgia-import-tariffs", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"duty_rate": "zero percent"}}]}, {"pair_id": "conflict_49b0585b8e8dded30e508913", "claim_ids": ["claim_0f762cccb9a8bb771a95397f", "claim_a6a7e3474922ef8383ae704f"], "query_ids": ["q_410"], "claims": [{"claim_id": "claim_0f762cccb9a8bb771a95397f", "quote": "Exempt cobalt products include ores and concentrates under 2605.00.00, oxides and hydroxides under 2822.00.00, cobalt sulphate under 2833.29.10, cobalt carbonate under 2836.99.10, as well as cobalt mattes, intermediate products, powders, and unwrought metal.", "url": "https://news.metal.com/newscontent/104021517-us-imposes-forced-labor-related-section-301-tariffs-lithium-ion-batteries-and-key-raw-materials-exempt", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "cobalt products"}}, {"claim_id": "claim_a6a7e3474922ef8383ae704f", "quote": "Exempt nickel products include ores and concentrates under 2604.00.00, mattes under 7501.10.00, oxides and hydroxides under 2825.40.00, nickel sulphate under 2833.24.00, and unwrought non-alloyed and alloyed nickel under 7502.10.00 and 7502.20.00.", "url": "https://news.metal.com/newscontent/104021517-us-imposes-forced-labor-related-section-301-tariffs-lithium-ion-batteries-and-key-raw-materials-exempt", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"affected_product": "nickel products", "hts_code": "7501.10.00"}}]}, {"pair_id": "conflict_acf8a771dff97f9bb7461baa", "claim_ids": ["claim_332ea1128d2e93e8849d6638", "claim_c6ccab6e8f93c46218f627a2"], "query_ids": ["q_410"], "claims": [{"claim_id": "claim_332ea1128d2e93e8849d6638", "quote": "However, batteries and a broad range of key battery raw materials are included in the exemption list. According to the final product list released by the Office of the United States Trade Representative (USTR), lithium-ion batteries under HTSUS 8507.60.00 will not be subject to the additional Section 301 tariffs.", "url": "https://news.metal.com/newscontent/104021517-us-imposes-forced-labor-related-section-301-tariffs-lithium-ion-batteries-and-key-raw-materials-exempt", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301", "legal_authority": "Office of the United States Trade Representative (USTR)", "affected_product": "lithium-ion batteries", "hts_code": "8507.60.00"}}, {"claim_id": "claim_c6ccab6e8f93c46218f627a2", "quote": "the tariff on battery parts and lithium-ion batteries for EVs will increase from 7.5% TO 25% THIS YEAR.", "url": "https://www.alixpartners.com/media/zwkcl4ec/impact-of-tariffs_sept-24.pdf", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 301 tariffs", "affected_product": "battery parts and lithium-ion batteries for EVs", "duty_rate": "25%", "effective_date": "THIS YEAR", "reported_policy_status": "set to rise further"}}]}]}

